using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
public sealed class DeliveryPresentation:MonoBehaviour {
 public int markerLayer=10,worldMarkerLayer=11;public Material vehicleMaterial,destinationMaterial;
 DeliveryManager manager;LineRenderer destination,vehicleRing;float completedAt=-1,refresh;PlayerMovement player;CanvasGroup hud;TMP_Text status,notification,money,mission,employeeLabel,vehicleLabel;int missionStep=-1;float missionPulse;Camera view;
 void Start(){manager=GetComponent<DeliveryManager>();SceneManager.activeSceneChanged+=Changed;Bind();destination=Ring("SelectedDestination",1.05f,destinationMaterial);vehicleRing=Ring("SelectedCompanyVehicle",1.65f,vehicleMaterial);destination.gameObject.SetActive(false);vehicleRing.gameObject.SetActive(false);}
 void Changed(Scene a,Scene b){Bind();}void OnDestroy(){SceneManager.activeSceneChanged-=Changed;if(hud!=null)Destroy(hud.gameObject);}
 void Bind(){if(hud!=null)Destroy(hud.gameObject);player=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene==SceneManager.GetActiveScene());if(player==null)return;view=player.CameraTransform.GetComponent<Camera>();money=player.GetComponentsInChildren<TMP_Text>(true).FirstOrDefault(t=>t.text.Contains("R$"));foreach(var label in player.GetComponentsInChildren<TMP_Text>(true)){if(label.text.Contains("Funcion"))employeeLabel=label.transform.parent.GetComponentsInChildren<TMP_Text>(true).FirstOrDefault(t=>t!=label&&int.TryParse(t.text,out _))??label;if(label.text.Contains("Veícul")||label.text.Contains("Veicul"))vehicleLabel=label.transform.parent.GetComponentsInChildren<TMP_Text>(true).FirstOrDefault(t=>t!=label&&int.TryParse(t.text,out _))??label;}BuildHud();}
 LineRenderer Ring(string name,float radius,Material material){var go=new GameObject(name);go.layer=worldMarkerLayer;go.transform.SetParent(transform,false);var line=go.AddComponent<LineRenderer>();line.useWorldSpace=false;line.loop=true;line.positionCount=48;line.widthMultiplier=.065f;line.sharedMaterial=material;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;line.receiveShadows=false;for(int i=0;i<48;i++){float angle=i/48f*Mathf.PI*2;line.SetPosition(i,new Vector3(Mathf.Cos(angle)*radius,.07f,Mathf.Sin(angle)*radius));}return line;}
 void Update(){if(manager==null)return;var order=manager.Selected;var point=order!=null?manager.Point(order.destinationId):null;bool done=order!=null&&order.status==DeliveryStatus.Completed;
  if(point!=null&&!done){completedAt=-1;destination.gameObject.SetActive(true);destination.transform.position=point.transform.position;destination.transform.localScale=Vector3.one*(1+.025f*Mathf.Sin(Time.time*2));destination.startColor=destination.endColor=Color.white;}else if(destination.gameObject.activeSelf){if(completedAt<0)completedAt=Time.time;float t=(Time.time-completedAt)/1.2f;destination.transform.localScale=Vector3.one*(1+t);destination.startColor=destination.endColor=new Color(1,1,1,1-t);if(t>=1)destination.gameObject.SetActive(false);}var selectedVehicle=order!=null?manager.fleet.FirstOrDefault(v=>v!=null&&v.Order==order):null;vehicleRing.gameObject.SetActive(selectedVehicle!=null);if(selectedVehicle!=null)vehicleRing.transform.position=selectedVehicle.transform.position;
  if(player==null||hud==null)return;hud.alpha=player.ControlsBlocked||GridShiftOperationsUI.ModalOpen?0:1;float half=Mathf.Tan(view.fieldOfView*.5f*Mathf.Deg2Rad)*.86f;hud.transform.localPosition=new Vector3(half*view.aspect-.19f,half-.17f,.86f);if(Time.unscaledTime<refresh)return;refresh=Time.unscaledTime+.3f;if(money!=null)money.text="R$ "+manager.Money.ToString("N0");int active=manager.orders.Count(o=>o.status!=DeliveryStatus.Completed),complete=manager.orders.Count-active;
  status.text="<color=#F0D047>ENTREGAS</color>  "+active+" ativas · "+complete+" concluídas";if(order!=null){string name=point!=null?point.displayName:order.destinationId;if(name.Length>32)name=name.Substring(0,30)+"…";float progress=done?1:Mathf.Min(.95f,order.travelledMeters/Mathf.Max(1,order.estimatedMeters));status.text+="\n"+(order.vehicleId??"Aguardando veículo")+" · "+(done?"<color=#72DCA0>Concluída</color>":StatusName(order.status))+"\n"+name+"\n"+Mathf.RoundToInt(progress*100)+"%  ·  #"+order.id.Substring(0,8);}else status.text+="\nCrie ou aceite um contrato pelo tablet.\nFrota: "+manager.fleet.Count(v=>v!=null&&v.Available)+" veículos livres";
  var company=manager.Company;if(company!=null&&company.Ready){if(employeeLabel!=null)employeeLabel.text=company.Employees.ToString();if(vehicleLabel!=null)vehicleLabel.text=manager.fleet.Count.ToString();var selected=company.Missions.Selected;if(selected!=null){if(missionStep!=selected.step){missionStep=selected.step;missionPulse=Time.unscaledTime;}mission.color=Color.Lerp(new Color(1,.85f,.25f),Color.white,Mathf.Clamp01((Time.unscaledTime-missionPulse)/.45f));mission.text=selected.name+" · "+Mathf.Min(selected.step+1,selected.objectives.Length)+"/"+selected.objectives.Length+"\n"+(selected.status==CompanyMissionStatus.Completed?"Concluída":selected.objectives[Mathf.Min(selected.step,selected.objectives.Length-1)]);}}
  notification.text=Time.unscaledTime-manager.NotificationAt<5?manager.LastNotification:GridShiftControls.KeyName(GSAction.Deliveries)+" · Operações     "+GridShiftControls.KeyName(GSAction.Map)+" · Mapa";
 }
 public static string StatusName(DeliveryStatus state){string[] names={"Aguardando veículo","Indo à coleta","Carregando","Em transporte","Descarregando","Concluída","Aguardando rota"};return (int)state>=0&&(int)state<names.Length?names[(int)state]:"Indisponível";}
 void BuildHud(){var go=new GameObject("DeliveryHUD",typeof(RectTransform),typeof(Canvas),typeof(CanvasGroup));go.transform.SetParent(player.CameraTransform,false);go.transform.localRotation=Quaternion.Euler(0,-5,0);go.transform.localScale=Vector3.one*.00072f;go.GetComponent<RectTransform>().sizeDelta=new Vector2(430,260);var c=go.GetComponent<Canvas>();c.renderMode=RenderMode.WorldSpace;c.worldCamera=view;hud=go.GetComponent<CanvasGroup>();hud.blocksRaycasts=false;hud.interactable=false;var bg=go.AddComponent<Image>();bg.color=new Color(.02f,.035f,.065f,.91f);bg.raycastTarget=false;GridShiftUITheme.Surface(bg,"Painel_Cartao_Informacoes");status=Text(go.transform,new Vector2(398,112),new Vector2(0,65),21);notification=Text(go.transform,new Vector2(398,30),new Vector2(0,-8),16);notification.color=new Color(.68f,.77f,.88f);mission=Text(go.transform,new Vector2(398,95),new Vector2(0,-75),17);}
 static TMP_Text Text(Transform parent,Vector2 size,Vector2 at,float font){var go=new GameObject("DeliveryStatus",typeof(RectTransform),typeof(TextMeshProUGUI));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=size;r.anchoredPosition=at;var text=go.GetComponent<TextMeshProUGUI>();text.fontSize=font;text.raycastTarget=false;text.color=Color.white;text.overflowMode=TextOverflowModes.Ellipsis;return text;}
}




